#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream one("one");
    std::ostringstream two("two");

    std::cout << "Before move, one = \"" << one.str() << '"' << " two = \"" << two.str()
              << "\"\n";

    *one.rdbuf() = std::move(*two.rdbuf());

    std::cout << "After move, one = \"" << one.str() << '"' << " two = \"" << two.str()
              << "\"\n";
}
